<script setup lang="ts">
import{computed,onMounted}from'vue';import{storeToRefs}from'pinia';import{RouterLink,useRoute}from'vue-router';import FinanceSubnav from'../components/FinanceSubnav.vue';import{useFinanceStore}from'../runtime/finance-store';import'./finance-views.css';import'./finance-receivable-views.css'
const store=useFinanceStore();const route=useRoute();const{writeoffs,receivableDocuments,receipts,error}=storeToRefs(store);const row=computed(()=>writeoffs.value.find(v=>v.id===String(route.params.writeoffId)));const money=(v:number)=>`¥${(v/100).toFixed(2)}`;const source=(kind:string,id:string)=>kind==='receipt'?receipts.value.find(v=>v.id===id)?.receiptNo??id:store.settlementSources.find(v=>v.id===id)?.label??`预收来源 ${id}`;const target=(id:string)=>receivableDocuments.value.find(v=>v.id===id);onMounted(async()=>{await Promise.all([store.loadWriteoffs(),store.loadReceipts(),store.loadReceivables()]);if(row.value)await store.loadSettlementSources(row.value.customerId)})
</script>
<template><section class="finance-page"><header class="finance-header"><div><h1>核销单详情</h1><p>完整保留来源—应收分配、现金与优惠拆分以及取消审计。</p></div></header><FinanceSubnav/><div v-if="error" class="finance-state error">{{error}}</div><template v-else-if="row"><div class="finance-summary"><article><span>现金/预收</span><strong>{{money(row.cashCents)}}</strong></article><article><span>优惠</span><strong>{{money(row.discountCents)}}</strong></article><article><span>核销总额</span><strong class="fin-income">{{money(row.amountCents)}}</strong></article><article><span>状态</span><strong>{{row.status==='active'?'有效':'已取消'}}</strong></article></div><div class="finance-panel detail-grid"><div><span>核销单号</span><strong>{{row.writeoffNo}}</strong></div><div><span>核销日期</span><strong>{{row.occurredAt}}</strong></div><div><span>客户</span><strong>{{row.customerId}}</strong></div><div><span>操作人</span><strong>{{row.operatorSnapshot.name}}</strong></div><div class="wide"><span>备注</span><strong>{{row.note??'—'}}</strong></div><div v-if="row.cancelInfo" class="wide"><span>取消审计</span><strong>{{row.cancelInfo.cancelledAt}} · {{row.cancelInfo.cancelledBy.name}} · {{row.cancelInfo.reason}}</strong></div></div><h2 class="section-title">分配明细</h2><div class="finance-table-wrap"><table class="finance-table"><thead><tr><th>来源</th><th>目标应收/订单</th><th class="fin-money">现金/预收</th><th class="fin-money">优惠</th><th class="fin-money">合计</th></tr></thead><tbody><tr v-for="part in row.allocations" :key="part.id"><td><RouterLink v-if="part.sourceKind==='receipt'" :to="`/finance/receipts/${part.sourceId}`">{{source(part.sourceKind,part.sourceId)}}</RouterLink><span v-else>{{source(part.sourceKind,part.sourceId)}}</span></td><td>{{target(part.receivableId)?.receivableNo??part.receivableId}}<small>{{target(part.receivableId)?.orderNo}}</small></td><td class="fin-money">{{money(part.cashCents)}}</td><td class="fin-money">{{money(part.discountCents)}}</td><td class="fin-money">{{money(part.cashCents+part.discountCents)}}</td></tr></tbody></table></div></template><div v-else class="finance-state">核销单不存在</div></section></template>
